//! Low level terminal interaction: tty detection and terminal size.

use std::env;

pub const STDIN: i32 = 0;
pub const STDOUT: i32 = 1;

mod sys {
    #[repr(C)]
    #[derive(Default)]
    pub struct WinSize {
        pub row: u16,
        pub col: u16,
        pub xpixel: u16,
        pub ypixel: u16,
    }

    extern "C" {
        pub fn isatty(fd: i32) -> i32;
        pub fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
}

#[cfg(target_os = "linux")]
const TIOCGWINSZ: u64 = 0x5413;
#[cfg(not(target_os = "linux"))]
const TIOCGWINSZ: u64 = 0x40087468;

pub fn is_tty(fd: i32) -> bool {
    unsafe { sys::isatty(fd) == 1 }
}

/// Terminal size of `fd`, if it is a terminal.
pub fn size_of(fd: i32) -> Option<(usize, usize)> {
    let mut ws = sys::WinSize::default();
    let rc = unsafe { sys::ioctl(fd, TIOCGWINSZ, &mut ws as *mut sys::WinSize) };
    if rc == 0 && ws.col > 0 {
        Some((ws.col as usize, ws.row as usize))
    } else {
        None
    }
}

/// Terminal dimensions as seen by the help formatter: the real terminal size of
/// stdout/stderr/stdin if any is a tty, otherwise the `COLUMNS`/`LINES` variables.
pub fn dimensions() -> (Option<usize>, Option<usize>) {
    for fd in [STDOUT, 2, STDIN] {
        if let Some((w, h)) = size_of(fd) {
            return (Some(w), Some(h));
        }
    }
    (parse_env("COLUMNS"), parse_env("LINES"))
}

fn parse_env(name: &str) -> Option<usize> {
    env::var(name).ok()?.trim().parse().ok()
}

/// The width bat uses for its own output.
pub fn output_width() -> Option<usize> {
    size_of(STDOUT).map(|(w, _)| w)
}

