//! Static description of the command line interface.
//!
//! The tables in this module drive both argument parsing and help rendering, so
//! that the two can never drift apart.

pub struct ArgSpec {
    pub id: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    /// Additional long names that are advertised in the help text.
    pub visible_aliases: &'static [&'static str],
    /// Additional long names that are accepted but not advertised.
    pub hidden_aliases: &'static [&'static str],
    pub value_name: Option<&'static str>,
    pub help: Option<&'static str>,
    pub long_help: Option<&'static str>,
    pub hidden: bool,
    /// `true` if repeating the flag is meaningful (`-pp`, several `-r`, ...).
    pub multiple: bool,
    pub possible_values: &'static [&'static str],
    /// Render a `[possible values: ..]` suffix in the help text.
    pub list_possible_values: bool,
    /// A `...` suffix after the flag name in the help text.
    pub variadic_marker: bool,
}

impl ArgSpec {
    const fn flag(id: &'static str) -> Self {
        ArgSpec {
            id,
            short: None,
            long: None,
            visible_aliases: &[],
            hidden_aliases: &[],
            value_name: None,
            help: None,
            long_help: None,
            hidden: false,
            multiple: false,
            possible_values: &[],
            list_possible_values: false,
            variadic_marker: false,
        }
    }

    pub fn takes_value(&self) -> bool {
        self.value_name.is_some()
    }

    /// The left hand column of the help entry, without the leading indent.
    pub fn key(&self) -> String {
        let mut s = String::new();
        match self.short {
            Some(c) => {
                s.push('-');
                s.push(c);
                if self.long.is_some() {
                    s.push_str(", ");
                } else {
                    s.push_str("  ");
                }
            }
            None => s.push_str("    "),
        }
        if let Some(long) = self.long {
            s.push_str("--");
            s.push_str(long);
        }
        if self.variadic_marker {
            s.push_str("...");
        }
        if let Some(v) = self.value_name {
            s.push(' ');
            s.push('<');
            s.push_str(v);
            s.push('>');
        }
        s
    }
}

macro_rules! args {
    ( $( { $id:expr $(, $field:ident = $val:expr )* $(,)? } ),* $(,)? ) => {
        &[ $( {
            #[allow(unused_mut)]
            let mut a = ArgSpec::flag($id);
            $( a.$field = $val; )*
            a
        } ),* ]
    };
}

