//! Rendering of the `--help` / `-h` screens.
//!
//! This reproduces the layout of the argument parser that the original tool is
//! built on: a two column layout when the key column is narrow enough, and a
//! "help on the next line" layout otherwise.

use super::spec::{ArgSpec, ABOUT_LONG, ABOUT_SHORT, AFTER_LONG_HELP, ARGS, CACHE_ABOUT,
                  CACHE_ARGS, POSITIONAL};
use crate::term;
use crate::width::display_width;

const TAB: usize = 4;
const INDENT: usize = 2;
const MAX_TERM_WIDTH: usize = 100;

pub fn term_width() -> usize {
    let cols = term::dimensions().0.unwrap_or(MAX_TERM_WIDTH);
    cols.min(MAX_TERM_WIDTH)
}

/// Wrap `text` to `width`, keeping the indentation of each source line on its
/// continuation lines and preserving explicit line breaks.
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let width = width.max(1);
    let mut out = Vec::new();
    for line in text.split('\n') {
        let indent_len = line.len() - line.trim_start_matches(' ').len();
        let indent: String = " ".repeat(indent_len);
        let body = &line[indent_len..];
        if body.is_empty() {
            out.push(line.to_string());
            continue;
        }
        let mut cur = indent.clone();
        let mut cur_w = indent_len;
        let mut first = true;
        for word in body.split(' ') {
            if word.is_empty() {
                // Preserve runs of spaces inside a line.
                if !first {
                    cur.push(' ');
                    cur_w += 1;
                }
                continue;
            }
            let w = display_width(word);
            if !first && cur_w + 1 + w > width {
                out.push(cur.trim_end().to_string());
                cur = indent.clone();
                cur_w = indent_len;
                cur.push_str(word);
                cur_w += w;
            } else {
                if !first {
                    cur.push(' ');
                    cur_w += 1;
                }
                cur.push_str(word);
                cur_w += w;
            }
            first = false;
        }
        out.push(cur.trim_end().to_string());
    }
    out
}

fn spec_vals(arg: &ArgSpec) -> String {
    let mut parts: Vec<String> = Vec::new();
    if !arg.visible_aliases.is_empty() {
        let list: Vec<String> = arg
            .visible_aliases
            .iter()
            .map(|a| format!("--{}", a))
            .collect();
        parts.push(format!("[aliases: {}]", list.join(", ")));
    }
    if arg.list_possible_values && !arg.possible_values.is_empty() {
        parts.push(format!(
            "[possible values: {}]",
            arg.possible_values.join(", ")
        ));
    }
    parts.join(" ")
}

fn help_text(arg: &ArgSpec, long: bool) -> String {
    let about = if long {
        arg.long_help.or(arg.help)
    } else {
        arg.help.or(arg.long_help)
    };
    let mut help = about.unwrap_or("").to_string();
    let sv = spec_vals(arg);
    if !sv.is_empty() {
        if !help.is_empty() {
            help.push_str(if long { "\n\n" } else { " " });
        }
        help.push_str(&sv);
    }
    help
}

fn builtin_help_text(id: &str, long: bool) -> Option<&'static str> {
    match id {
        "help" => Some(if long {
            "Print help (see a summary with '-h')"
        } else {
            "Print help (see more with '--help')"
        }),
        "version" => Some("Print version"),
        _ => None,
    }
}

fn section(out: &mut String, title: &str, args: &[&ArgSpec], long: bool, term_w: usize) {
    if args.is_empty() {
        return;
    }
    let longest = args
        .iter()
        .map(|a| display_width(&a.key()))
        .max()
        .unwrap_or(2)
        .max(2);

    let taken = longest + TAB * 2;
    let next_line = long
        || (term_w >= taken
            && (taken as f32 / term_w as f32) > 0.40
            && args.iter().any(|a| {
                let h = match builtin_help_text(a.id, long) {
                    Some(t) => t.to_string(),
                    None => help_text(a, long),
                };
                display_width(&h) > term_w - taken
            }));

    out.push_str(title);
    out.push_str(":\n");

    for arg in args {
        let key = arg.key();
        let text = match builtin_help_text(arg.id, long) {
            Some(t) => t.to_string(),
            None => help_text(arg, long),
        };
        if next_line {
            out.push_str(&" ".repeat(INDENT));
            out.push_str(&key);
            out.push('\n');
            if !text.is_empty() {
                let pad = INDENT + TAB * 2;
                for l in wrap(&text, term_w.saturating_sub(pad)) {
                    out.push_str(&" ".repeat(pad));
                    out.push_str(&l);
                    out.push('\n');
                }
            }
            out.push('\n');
        } else {
            let col = INDENT + longest + INDENT;
            out.push_str(&" ".repeat(INDENT));
            out.push_str(&key);
            if text.is_empty() {
                out.push('\n');
                continue;
            }
            let pad = longest - display_width(&key) + INDENT;
            out.push_str(&" ".repeat(pad));
            let lines = wrap(&text, term_w.saturating_sub(col));
            for (i, l) in lines.iter().enumerate() {
                if i > 0 {
                    out.push_str(&" ".repeat(col));
                }
                out.push_str(l);
                out.push('\n');
            }
        }
    }
    if next_line {
        // The blank line after the last entry doubles as the section separator.
        out.pop();
    }
}

/// Render the top level help screen.
pub fn render(long: bool) -> String {
    let term_w = term_width();
    let mut out = String::new();
    out.push_str(if long { ABOUT_LONG } else { ABOUT_SHORT });
    out.push_str("\n\n");
    out.push_str("Usage: bat [OPTIONS] [FILE]...\n       bat <COMMAND>\n\n");

    let positional = [&POSITIONAL];
    section(&mut out, "Arguments", &positional, long, term_w);
    out.push('\n');

    let opts: Vec<&ArgSpec> = ARGS.iter().filter(|a| visible(a, long)).collect();
    section(&mut out, "Options", &opts, long, term_w);

    if long {
        out.push('\n');
        for l in wrap(AFTER_LONG_HELP, term_w) {
            out.push_str(&l);
            out.push('\n');
        }
    }
    out
}

fn visible(a: &ArgSpec, _long: bool) -> bool {
    !a.hidden && (a.help.is_some() || a.long_help.is_some() || a.id == "help" || a.id == "version")
}

/// Render the help screen of the `cache` subcommand.
pub fn render_cache(bin: &str, long: bool) -> String {
    let term_w = term_width();
    let mut out = String::new();
    out.push_str(CACHE_ABOUT);
    out.push_str("\n\n");
    out.push_str(&format!("Usage: {} cache [OPTIONS]\n\n", bin));
    let opts: Vec<&ArgSpec> = CACHE_ARGS.iter().collect();
    section(&mut out, "Options", &opts, long, term_w);
    out
}

