//! Command line parsing.

use super::spec::{ArgSpec, ARGS, CACHE_ARGS};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Source {
    Config,
    Env,
    Cli,
}

#[derive(Debug)]
pub struct Occurrence {
    pub value: Option<String>,
    pub source: Source,
}

#[derive(Debug, Default)]
pub struct Matches {
    entries: Vec<(&'static str, Occurrence)>,
    pub positional: Vec<String>,
    pub subcommand: Option<String>,
}

impl Matches {
    pub fn present(&self, id: &str) -> bool {
        self.entries.iter().any(|(k, _)| *k == id)
    }
    pub fn count(&self, id: &str) -> usize {
        self.entries.iter().filter(|(k, _)| *k == id).count()
    }
    /// Last value given for `id`.
    pub fn value(&self, id: &str) -> Option<&str> {
        self.entries
            .iter()
            .rev()
            .find(|(k, _)| *k == id)
            .and_then(|(_, o)| o.value.as_deref())
    }
    pub fn values(&self, id: &str) -> Vec<&str> {
        self.entries
            .iter()
            .filter(|(k, _)| *k == id)
            .filter_map(|(_, o)| o.value.as_deref())
            .collect()
    }
    pub fn occurrences(&self, id: &str) -> Vec<&Occurrence> {
        self.entries
            .iter()
            .filter(|(k, _)| *k == id)
            .map(|(_, o)| o)
            .collect()
    }
    fn push(&mut self, id: &'static str, value: Option<String>, source: Source) {
        self.entries.push((id, Occurrence { value, source }));
    }
}

pub struct ParseError {
    pub message: String,
    pub show_usage: bool,
    pub try_help: bool,
}

impl ParseError {
    fn new(message: String) -> Self {
        ParseError {
            message,
            show_usage: false,
            try_help: false,
        }
    }
}

type R<T> = Result<T, ParseError>;

fn lookup<'a>(table: &'a [ArgSpec], name: &str) -> Option<&'a ArgSpec> {
    table.iter().find(|a| {
        a.long == Some(name)
            || a.visible_aliases.contains(&name)
            || a.hidden_aliases.contains(&name)
    })
}

fn lookup_short(table: &[ArgSpec], c: char) -> Option<&ArgSpec> {
    table.iter().find(|a| a.short == Some(c))
}

fn similar(table: &[ArgSpec], name: &str) -> Option<String> {
    let mut best: Option<(usize, String)> = None;
    for a in table {
        let mut candidates: Vec<&str> = Vec::new();
        if let Some(l) = a.long {
            candidates.push(l);
        }
        for al in a.visible_aliases {
            candidates.push(al);
        }
        for c in candidates {
            let d = edit_distance(name, c);
            let limit = (c.len() / 3).max(2);
            if d <= limit {
                if best.as_ref().map(|(bd, _)| d < *bd).unwrap_or(true) {
                    best = Some((d, format!("--{}", c)));
                }
            }
        }
    }
    best.map(|(_, s)| s)
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

fn invalid_value(arg: &ArgSpec, value: &str) -> ParseError {
    ParseError::new(format!(
        "error: invalid value '{}' for '{}'\n  [possible values: {}]\n",
        value,
        arg.key().trim_start_matches(' ').trim_start(),
        arg.possible_values.join(", ")
    ))
}

fn arg_display(arg: &ArgSpec) -> String {
    let mut s = String::new();
    if let Some(l) = arg.long {
        s.push_str("--");
        s.push_str(l);
    } else if let Some(c) = arg.short {
        s.push('-');
        s.push(c);
    }
    if let Some(v) = arg.value_name {
        s.push_str(&format!(" <{}>", v));
    }
    s
}

fn check_value(arg: &ArgSpec, value: &str) -> R<()> {
    if !arg.possible_values.is_empty() && !arg.possible_values.contains(&value) {
        return Err(ParseError::new(format!(
            "error: invalid value '{}' for '{}'\n  [possible values: {}]\n",
            value,
            arg_display(arg),
            arg.possible_values.join(", ")
        )));
    }
    Ok(())
}

fn missing_value(arg: &ArgSpec) -> ParseError {
    let mut msg = format!(
        "error: a value is required for '{}' but none was supplied\n",
        arg_display(arg)
    );
    if !arg.possible_values.is_empty() {
        msg.push_str(&format!(
            "  [possible values: {}]\n",
            arg.possible_values.join(", ")
        ));
    }
    ParseError::new(msg)
}

/// Parse a list of `(argument, source)` pairs.
pub fn parse(items: &[(String, Source)]) -> R<Matches> {
    let mut m = Matches::default();
    let mut i = 0;
    let mut no_more_flags = false;

    // The `cache` subcommand swallows everything after it.
    if let Some((first, _)) = items.first() {
        if first == "cache" {
            m.subcommand = Some("cache".to_string());
            let rest: Vec<(String, Source)> = items[1..].to_vec();
            parse_into(&rest, CACHE_ARGS, &mut m)?;
            return Ok(m);
        }
    }

    while i < items.len() {
        let (raw, source) = (&items[i].0, items[i].1);
        i += 1;
        if no_more_flags {
            m.positional.push(raw.clone());
            continue;
        }
        if raw == "--" {
            no_more_flags = true;
            continue;
        }
        if raw == "-" || !raw.starts_with('-') {
            m.positional.push(raw.clone());
            continue;
        }
        if let Some(name) = raw.strip_prefix("--") {
            let (name, inline) = match name.find('=') {
                Some(p) => (&name[..p], Some(name[p + 1..].to_string())),
                None => (name, None),
            };
            let arg = match lookup(ARGS, name) {
                Some(a) => a,
                None => {
                    let mut msg =
                        format!("error: unexpected argument '--{}' found\n\n", name);
                    match similar(ARGS, name) {
                        Some(s) => msg.push_str(&format!(
                            "  tip: a similar argument exists: '{}'\n",
                            s
                        )),
                        None => msg.push_str(&format!(
                            "  tip: to pass '--{}' as a value, use '-- --{}'\n",
                            name, name
                        )),
                    }
                    let mut e = ParseError::new(msg);
                    e.show_usage = true;
                    return Err(e);
                }
            };
            if arg.takes_value() {
                let value = match inline {
                    Some(v) => v,
                    None => {
                        if i < items.len() {
                            let v = items[i].0.clone();
                            i += 1;
                            v
                        } else {
                            return Err(missing_value(arg));
                        }
                    }
                };
                check_value(arg, &value)?;
                m.push(arg.id, Some(value), source);
            } else {
                if inline.is_some() {
                    return Err(ParseError::new(format!(
                        "error: unexpected value '{}' for '--{}' found; no more were expected\n",
                        inline.unwrap(),
                        name
                    )));
                }
                m.push(arg.id, None, source);
            }
            continue;
        }
        // Short flags, possibly bundled.
        let chars: Vec<char> = raw[1..].chars().collect();
        let mut k = 0;
        while k < chars.len() {
            let c = chars[k];
            k += 1;
            let arg = match lookup_short(ARGS, c) {
                Some(a) => a,
                None => {
                    let mut msg = format!("error: unexpected argument '-{}' found\n\n", c);
                    msg.push_str(&format!(
                        "  tip: to pass '-{}' as a value, use '-- -{}'\n",
                        c, c
                    ));
                    let mut e = ParseError::new(msg);
                    e.show_usage = true;
                    return Err(e);
                }
            };
            if arg.takes_value() {
                let rest: String = chars[k..].iter().collect();
                let value = if !rest.is_empty() {
                    k = chars.len();
                    rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest)
                } else if i < items.len() {
                    let v = items[i].0.clone();
                    i += 1;
                    v
                } else {
                    return Err(missing_value(arg));
                };
                check_value(arg, &value)?;
                m.push(arg.id, Some(value), source);
            } else {
                m.push(arg.id, None, source);
            }
        }
    }
    Ok(m)
}

fn parse_into(items: &[(String, Source)], table: &'static [ArgSpec], m: &mut Matches) -> R<()> {
    let mut i = 0;
    while i < items.len() {
        let raw = &items[i].0;
        let source = items[i].1;
        i += 1;
        if !raw.starts_with('-') {
            m.positional.push(raw.clone());
            continue;
        }
        if let Some(name) = raw.strip_prefix("--") {
            let (name, inline) = match name.find('=') {
                Some(p) => (&name[..p], Some(name[p + 1..].to_string())),
                None => (name, None),
            };
            let arg = match lookup(table, name) {
                Some(a) => a,
                None => {
                    let mut e = ParseError::new(format!(
                        "error: unexpected argument '--{}' found\n",
                        name
                    ));
                    e.show_usage = true;
                    e.try_help = true;
                    return Err(e);
                }
            };
            if arg.takes_value() {
                let value = match inline {
                    Some(v) => v,
                    None => {
                        if i < items.len() {
                            let v = items[i].0.clone();
                            i += 1;
                            v
                        } else {
                            return Err(missing_value(arg));
                        }
                    }
                };
                m.push(arg.id, Some(value), source);
            } else {
                m.push(arg.id, None, source);
            }
            continue;
        }
        for c in raw[1..].chars() {
            match lookup_short(table, c) {
                Some(a) => m.push(a.id, None, source),
                None => {
                    let mut e =
                        ParseError::new(format!("error: unexpected argument '-{}' found\n", c));
                    e.show_usage = true;
                    e.try_help = true;
                    return Err(e);
                }
            }
        }
    }
    Ok(())
}

#[allow(dead_code)]
fn unused(a: &ArgSpec, v: &str) -> ParseError {
    invalid_value(a, v)
}

