//! Style components and their resolution.

use std::collections::BTreeSet;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Component {
    Changes,
    Grid,
    Rule,
    HeaderFilename,
    HeaderFilesize,
    LineNumbers,
    Snip,
}

pub const DEFAULT: &[Component] = &[
    Component::Changes,
    Component::Grid,
    Component::HeaderFilename,
    Component::LineNumbers,
    Component::Snip,
];

pub const FULL: &[Component] = &[
    Component::Changes,
    Component::Grid,
    Component::Rule,
    Component::HeaderFilename,
    Component::HeaderFilesize,
    Component::LineNumbers,
    Component::Snip,
];

#[derive(Clone, Debug, Default)]
pub struct Components(pub BTreeSet<Component>);

impl Components {
    pub fn none() -> Self {
        Components(BTreeSet::new())
    }
    pub fn from(list: &[Component]) -> Self {
        Components(list.iter().copied().collect())
    }
    pub fn changes(&self) -> bool {
        self.0.contains(&Component::Changes)
    }
    pub fn grid(&self) -> bool {
        self.0.contains(&Component::Grid)
    }
    pub fn rule(&self) -> bool {
        self.0.contains(&Component::Rule)
    }
    pub fn header_filename(&self) -> bool {
        self.0.contains(&Component::HeaderFilename)
    }
    pub fn header_filesize(&self) -> bool {
        self.0.contains(&Component::HeaderFilesize)
    }
    pub fn header(&self) -> bool {
        self.header_filename() || self.header_filesize()
    }
    pub fn numbers(&self) -> bool {
        self.0.contains(&Component::LineNumbers)
    }
    pub fn snip(&self) -> bool {
        self.0.contains(&Component::Snip)
    }
    pub fn any(&self) -> bool {
        !self.0.is_empty()
    }
}

/// One `--style=..` value: either a replacement or a `+`/`-` modification.
pub enum StyleSet {
    Replace(Vec<Component>),
    Modify(Vec<(bool, Component)>),
}

fn expand(name: &str) -> Option<Vec<Component>> {
    Some(match name {
        "default" | "auto" => DEFAULT.to_vec(),
        "full" => FULL.to_vec(),
        "plain" => vec![],
        "changes" => vec![Component::Changes],
        "grid" => vec![Component::Grid],
        "rule" => vec![Component::Rule],
        "header" | "header-filename" => vec![Component::HeaderFilename],
        "header-filesize" => vec![Component::HeaderFilesize],
        "numbers" => vec![Component::LineNumbers],
        "snip" => vec![Component::Snip],
        _ => return None,
    })
}

/// Parse a comma separated list of components.
pub fn parse_set(value: &str) -> Result<StyleSet, String> {
    let items: Vec<&str> = value.split(',').collect();
    let all_modifiers = items
        .iter()
        .all(|i| i.starts_with('+') || i.starts_with('-'));
    if all_modifiers && !items.is_empty() {
        let mut out = Vec::new();
        for item in items {
            let add = item.starts_with('+');
            let name = &item[1..];
            let comps = expand(name).ok_or_else(|| format!("Unknown style '{}'", name))?;
            for c in comps {
                out.push((add, c));
            }
        }
        Ok(StyleSet::Modify(out))
    } else {
        let mut out = Vec::new();
        for item in items {
            let comps = expand(item).ok_or_else(|| format!("Unknown style '{}'", item))?;
            out.extend(comps);
        }
        Ok(StyleSet::Replace(out))
    }
}

/// Apply the ordered list of style sets on top of the default set.
pub fn resolve(sets: &[StyleSet]) -> Components {
    let mut current: BTreeSet<Component> = DEFAULT.iter().copied().collect();
    for set in sets {
        match set {
            StyleSet::Replace(list) => {
                current = list.iter().copied().collect();
            }
            StyleSet::Modify(list) => {
                for (add, c) in list {
                    if *add {
                        current.insert(*c);
                    } else {
                        current.remove(c);
                    }
                }
            }
        }
    }
    Components(current)
}

