//! Resolution of the effective configuration from arguments and environment.

use std::env;
use std::path::PathBuf;

use crate::cli::parse::{Matches, Source};
use crate::style::{self, Components, StyleSet};
use crate::term;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum WrapMode {
    NoWrapping,
    Character,
    Word,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BinaryBehavior {
    NoPrinting,
    AsText,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NonprintableNotation {
    Unicode,
    Caret,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StripAnsi {
    Auto,
    Always,
    Never,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PagingMode {
    Always,
    QuitIfOneScreen,
    Never,
}

#[derive(Clone, Debug)]
pub struct LineRange {
    pub lower: usize,
    pub upper: usize,
}

#[derive(Clone, Debug, Default)]
pub struct LineRanges {
    pub ranges: Vec<LineRange>,
}

impl LineRanges {
    pub fn all(&self) -> bool {
        self.ranges.is_empty()
    }
    pub fn contains(&self, line: usize) -> bool {
        self.ranges.is_empty()
            || self
                .ranges
                .iter()
                .any(|r| line >= r.lower && line <= r.upper)
    }
    /// Highest line that can still be inside one of the ranges.
    pub fn max_line(&self) -> Option<usize> {
        if self.ranges.is_empty() {
            return None;
        }
        self.ranges.iter().map(|r| r.upper).max()
    }
}

pub struct Config {
    pub language: Option<String>,
    pub fallback_syntax: Option<String>,
    pub show_nonprintable: bool,
    pub nonprintable_notation: NonprintableNotation,
    pub binary: BinaryBehavior,
    pub wrapping: WrapMode,
    pub colored_output: bool,
    pub true_color: bool,
    pub use_italic_text: bool,
    pub style_components: Components,
    pub tab_width: usize,
    pub theme: String,
    pub visible_lines: VisibleLines,
    pub line_ranges: LineRanges,
    pub highlighted_lines: LineRanges,
    pub term_width: usize,
    pub squeeze_lines: Option<usize>,
    pub strip_ansi: StripAnsi,
    pub file_names: Vec<String>,
    pub paging_mode: PagingMode,
    pub pager: Option<String>,
    pub quiet_empty: bool,
    pub unbuffered: bool,
    pub set_terminal_title: bool,
    pub syntax_mappings: Vec<(String, String)>,
    pub ignored_suffixes: Vec<String>,
    pub diff_context: usize,
    pub interactive: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum VisibleLines {
    Ranges,
    DiffContext,
}

pub fn env_str(name: &str) -> Option<String> {
    match env::var(name) {
        Ok(v) => Some(v),
        Err(_) => None,
    }
}

fn env_nonempty(name: &str) -> Option<String> {
    env_str(name).filter(|v| !v.is_empty())
}

pub fn config_dir() -> PathBuf {
    if let Some(p) = env_nonempty("BAT_CONFIG_DIR") {
        return PathBuf::from(p);
    }
    if let Some(p) = env_nonempty("XDG_CONFIG_HOME") {
        let mut p = PathBuf::from(p);
        p.push("bat");
        return p;
    }
    let mut p = PathBuf::from(env_str("HOME").unwrap_or_default());
    p.push(".config");
    p.push("bat");
    p
}

pub fn config_file() -> PathBuf {
    if let Some(p) = env_nonempty("BAT_CONFIG_PATH") {
        return PathBuf::from(p);
    }
    let mut p = config_dir();
    p.push("config");
    p
}

pub fn cache_dir() -> PathBuf {
    if let Some(p) = env_nonempty("BAT_CACHE_PATH") {
        return PathBuf::from(p);
    }
    if let Some(p) = env_nonempty("XDG_CACHE_HOME") {
        let mut p = PathBuf::from(p);
        p.push("bat");
        return p;
    }
    let mut p = PathBuf::from(env_str("HOME").unwrap_or_default());
    p.push(".cache");
    p.push("bat");
    p
}

/// Split a configuration file into individual arguments.
pub fn split_config(contents: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in contents.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        out.extend(split_shell_words(line));
    }
    out
}

/// Very small shell-like tokenizer: handles single and double quotes.
pub fn split_shell_words(line: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut have = false;
    let mut quote: Option<char> = None;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match quote {
            Some(q) => {
                if c == q {
                    quote = None;
                } else {
                    cur.push(c);
                }
            }
            None => match c {
                '"' | '\'' => {
                    quote = Some(c);
                    have = true;
                }
                ' ' | '\t' => {
                    if have || !cur.is_empty() {
                        out.push(std::mem::take(&mut cur));
                        have = false;
                    }
                }
                '\\' => {
                    if let Some(n) = chars.next() {
                        cur.push(n);
                    }
                }
                _ => cur.push(c),
            },
        }
    }
    if have || !cur.is_empty() {
        out.push(cur);
    }
    out
}

fn parse_width(spec: &str, actual: usize) -> Option<usize> {
    let spec = spec.trim();
    if let Some(rest) = spec.strip_prefix('+') {
        let d: isize = rest.parse().ok()?;
        Some((actual as isize + d).max(0) as usize)
    } else if let Some(rest) = spec.strip_prefix('-') {
        let d: isize = rest.parse().ok()?;
        Some((actual as isize - d).max(0) as usize)
    } else {
        spec.parse().ok()
    }
}

pub const DEFAULT_TERM_WIDTH: usize = 80;

pub struct Resolved {
    pub config: Config,
    pub warnings: Vec<String>,
}

pub fn resolve(m: &Matches, interactive: bool) -> Result<Resolved, String> {
    let mut warnings = Vec::new();

    let color_arg = m.value("color").map(|s| s.to_string());
    let no_color = env::var_os("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false);
    let force = m.present("force-colorization");
    let colored_output = if force {
        true
    } else {
        match color_arg.as_deref() {
            Some("always") => true,
            Some("never") => false,
            _ => interactive && !no_color,
        }
    };

    let decorations = if force {
        Some("always")
    } else {
        m.value("decorations")
    };
    let decorations_on = match decorations {
        Some("never") => false,
        Some("always") => true,
        _ => interactive || color_arg.as_deref() == Some("always") || force,
    };

    // ---- style components -------------------------------------------------
    let mut sets: Vec<StyleSet> = Vec::new();
    for occ in m.occurrences("style") {
        if occ.source == Source::Config {
            if let Some(v) = &occ.value {
                sets.push(style::parse_set(v)?);
            }
        }
    }
    if let Some(v) = env_nonempty("BAT_STYLE") {
        sets.push(style::parse_set(&v)?);
    }
    for occ in m.occurrences("style") {
        if occ.source != Source::Config {
            if let Some(v) = &occ.value {
                sets.push(style::parse_set(v)?);
            }
        }
    }
    let mut components = style::resolve(&sets);
    if m.present("number") {
        components = Components::from(&[style::Component::LineNumbers]);
    }
    if m.count("plain") > 0 {
        components = Components::none();
    }
    if !decorations_on {
        components = Components::none();
    }

    // ---- terminal width ---------------------------------------------------
    let actual_width = term::output_width().unwrap_or(DEFAULT_TERM_WIDTH);
    let width_spec = m
        .value("terminal-width")
        .map(|s| s.to_string())
        .or_else(|| env_nonempty("BAT_WIDTH"));
    let term_width = match width_spec {
        Some(s) => parse_width(&s, actual_width).ok_or_else(|| {
            format!(
                "error: invalid value '{}' for '--terminal-width <width>': invalid digit found in string\n",
                s
            )
        })?,
        None => actual_width,
    };
    if term_width == 0 {
        return Err(
            "error: invalid value '0' for '--terminal-width <width>': terminal width cannot be zero\n"
                .to_string(),
        );
    }

    // ---- wrapping ---------------------------------------------------------
    let wrapping = if m.present("chop-long-lines") {
        WrapMode::NoWrapping
    } else {
        match m.value("wrap") {
            Some("character") => WrapMode::Character,
            Some("never") => WrapMode::NoWrapping,
            Some("word") => WrapMode::Word,
            _ => {
                if interactive || decorations_on || colored_output {
                    WrapMode::Character
                } else {
                    WrapMode::NoWrapping
                }
            }
        }
    };

    // ---- tabs -------------------------------------------------------------
    let tab_spec = m
        .value("tabs")
        .map(|s| s.to_string())
        .or_else(|| env_nonempty("BAT_TABS"));
    let tab_width = match tab_spec {
        Some(s) => s.trim().parse::<usize>().map_err(|_| {
            format!(
                "error: invalid value '{}' for '--tabs <T>': must be a number\n",
                s
            )
        })?,
        None => 4,
    };

    // ---- theme ------------------------------------------------------------
    let theme = crate::theme::select(m, interactive, &mut warnings);

    // ---- ranges -----------------------------------------------------------
    let mut line_ranges = LineRanges::default();
    for v in m.values("line-range") {
        line_ranges.ranges.push(crate::ranges::parse(v)?);
    }
    let mut highlighted = LineRanges::default();
    for v in m.values("highlight-line") {
        highlighted.ranges.push(crate::ranges::parse(v)?);
    }

    let squeeze_lines = if m.present("squeeze-limit") {
        Some(
            m.value("squeeze-limit")
                .unwrap()
                .parse::<usize>()
                .map_err(|_| {
                    format!(
                        "error: invalid value '{}' for '--squeeze-limit <squeeze-limit>': invalid digit found in string\n",
                        m.value("squeeze-limit").unwrap()
                    )
                })?,
        )
    } else if m.present("squeeze-blank") {
        Some(1)
    } else {
        None
    };

    let mut syntax_mappings = Vec::new();
    for v in m.values("map-syntax") {
        match v.rsplit_once(':') {
            Some((glob, syntax)) => syntax_mappings.push((glob.to_string(), syntax.to_string())),
            None => {
                return Err(format!(
                    "error: invalid value '{}' for '--map-syntax <glob:syntax>': invalid syntax mapping. The format of the -m/--map-syntax option is '<glob-pattern>:<syntax-name>'. For example: '*.cpp:C++'.\n",
                    v
                ))
            }
        }
    }

    let paging_mode = resolve_paging(m, interactive);

    let strip_ansi = match m.value("strip-ansi") {
        Some("always") => StripAnsi::Always,
        Some("auto") => StripAnsi::Auto,
        _ => StripAnsi::Never,
    };

    let diff_context = m
        .value("diff-context")
        .and_then(|s| s.parse().ok())
        .unwrap_or(2);

    let config = Config {
        language: m.value("language").map(|s| s.to_string()),
        fallback_syntax: m.value("fallback-syntax").map(|s| s.to_string()),
        show_nonprintable: m.present("show-all"),
        nonprintable_notation: match m.value("nonprintable-notation") {
            Some("caret") => NonprintableNotation::Caret,
            _ => NonprintableNotation::Unicode,
        },
        binary: match m.value("binary") {
            Some("as-text") => BinaryBehavior::AsText,
            _ => BinaryBehavior::NoPrinting,
        },
        wrapping,
        colored_output,
        true_color: crate::theme::truecolor_available(),
        use_italic_text: m.value("italic-text") == Some("always"),
        style_components: components,
        tab_width,
        theme,
        visible_lines: if m.present("diff") {
            VisibleLines::DiffContext
        } else {
            VisibleLines::Ranges
        },
        line_ranges,
        highlighted_lines: highlighted,
        term_width,
        squeeze_lines,
        strip_ansi,
        file_names: m.values("file-name").iter().map(|s| s.to_string()).collect(),
        paging_mode,
        pager: m.value("pager").map(|s| s.to_string()),
        quiet_empty: m.present("quiet-empty"),
        unbuffered: m.present("unbuffered"),
        set_terminal_title: m.present("set-terminal-title"),
        syntax_mappings,
        ignored_suffixes: m
            .values("ignored-suffix")
            .iter()
            .map(|s| s.to_string())
            .collect(),
        diff_context,
        interactive,
    };
    Ok(Resolved { config, warnings })
}

fn resolve_paging(m: &Matches, interactive: bool) -> PagingMode {
    let mut mode = m.value("paging").map(|s| s.to_string());
    if m.present("no-paging") || m.count("plain") > 1 {
        mode = Some("never".to_string());
    }
    if mode.is_none() {
        if let Some(v) = env_nonempty("BAT_PAGING") {
            mode = Some(v);
        }
    }
    match mode.as_deref() {
        Some("always") => PagingMode::Always,
        Some("never") => PagingMode::Never,
        _ => {
            if interactive {
                PagingMode::QuitIfOneScreen
            } else {
                PagingMode::Never
            }
        }
    }
}

