            }
        }
    }
    let mut components = style::resolve(&sets);
    if m.present("number") {
        components = Components::from(&[style::Component::LineNumbers]);
    }
    if m.count("plain") > 0 {
        components = Components::none();
    }
    if !decorations_on {
        components = Components::none();
    }

    // ---- terminal width ---------------------------------------------------
    let actual_width = term::output_width().unwrap_or(DEFAULT_TERM_WIDTH);
    let width_spec = m
        .value("terminal-width")
        .map(|s| s.to_string())
        .or_else(|| env_nonempty("BAT_WIDTH"));
    let term_width = match width_spec {
        Some(s) => parse_width(&s, actual_width).ok_or_else(|| {
            format!(
                "error: invalid value '{}' for '--terminal-width <width>': invalid digit found in string\n",
                s
            )
        })?,
        None => actual_width,
    };
    if term_width == 0 {
        return Err(
            "error: invalid value '0' for '--terminal-width <width>': terminal width cannot be zero\n"
                .to_string(),
        );
    }

    // ---- wrapping ---------------------------------------------------------
    let wrapping = if m.present("chop-long-lines") {
        WrapMode::NoWrapping
    } else {
        match m.value("wrap") {
            Some("character") => WrapMode::Character,
            Some("never") => WrapMode::NoWrapping,
            Some("word") => WrapMode::Word,
            _ => {
                if interactive || decorations_on || colored_output {
                    WrapMode::Character
                } else {
                    WrapMode::NoWrapping
                }
            }
        }
    };

    // ---- tabs -------------------------------------------------------------
    let tab_spec = m
        .value("tabs")
        .map(|s| s.to_string())
        .or_else(|| env_nonempty("BAT_TABS"));
    let tab_width = match tab_spec {
        Some(s) => s.trim().parse::<usize>().map_err(|_| {
            format!(
                "error: invalid value '{}' for '--tabs <T>': must be a number\n",
                s
            )
        })?,
        None => 4,
    };

    // ---- theme ------------------------------------------------------------
    let theme = crate::theme::select(m, interactive, &mut warnings);

    // ---- ranges -----------------------------------------------------------
    let mut line_ranges = LineRanges::default();
    for v in m.values("line-range") {
        line_ranges.ranges.push(crate::ranges::parse(v)?);
    }
    let mut highlighted = LineRanges::default();
    for v in m.values("highlight-line") {
        highlighted.ranges.push(crate::ranges::parse(v)?);
    }

    let squeeze_lines = if m.present("squeeze-limit") {
        Some(
            m.value("squeeze-limit")
                .unwrap()
                .parse::<usize>()
