        theme,
        visible_lines: if m.present("diff") {
            VisibleLines::DiffContext
        } else {
            VisibleLines::Ranges
        },
        line_ranges,
        highlighted_lines: highlighted,
        term_width,
        squeeze_lines,
        strip_ansi,
        file_names: m.values("file-name").iter().map(|s| s.to_string()).collect(),
        paging_mode,
        pager: m.value("pager").map(|s| s.to_string()),
        quiet_empty: m.present("quiet-empty"),
        unbuffered: m.present("unbuffered"),
        set_terminal_title: m.present("set-terminal-title"),
        syntax_mappings,
