//! The little range language shared by `--line-range` and `--highlight-line`.

use crate::config::{LineRange, LineRanges};

pub const OPEN: usize = usize::MAX;

/// A range as written on the command line. Negative bounds are relative to the
/// end of the file and are only resolved for `--line-range`.
#[derive(Clone, Copy, Debug)]
pub struct Raw {
    pub lower: i128,
    pub upper: i128,
}

fn parse_signed(s: &str) -> Result<i128, String> {
    parse_int::<i128>(s)
}

fn parse_unsigned(s: &str) -> Result<i128, String> {
    let v: u64 = parse_int(s)?;
    Ok(v as i128)
}

trait IntLike: Sized {
    fn parse_from(s: &str) -> Result<Self, String>;
}

impl IntLike for i128 {
    fn parse_from(s: &str) -> Result<Self, String> {
        parse_rust_int(s, true)
    }
}

impl IntLike for u64 {
    fn parse_from(s: &str) -> Result<Self, String> {
        let v = parse_rust_int(s, false)?;
        if v > u64::MAX as i128 {
            return Err("number too large to fit in target type".to_string());
        }
        Ok(v as u64)
    }
}

fn parse_int<T: IntLike>(s: &str) -> Result<T, String> {
    T::parse_from(s)
}

/// Mimics Rust's `str::parse::<uNN/iNN>()` error messages.
fn parse_rust_int(s: &str, signed: bool) -> Result<i128, String> {
    if s.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    let (neg, digits) = if let Some(r) = s.strip_prefix('-') {
        if !signed {
            return Err("invalid digit found in string".to_string());
        }
        (true, r)
    } else if let Some(r) = s.strip_prefix('+') {
        (false, r)
    } else {
        (false, s)
    };
    if digits.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    let mut value: i128 = 0;
    for c in digits.chars() {
        let d = match c.to_digit(10) {
            Some(d) => d as i128,
            None => return Err("invalid digit found in string".to_string()),
        };
        value = value * 10 + d;
        if value > u64::MAX as i128 {
            return Err("number too large to fit in target type".to_string());
        }
    }
    Ok(if neg { -value } else { value })
}

pub fn parse_raw(s: &str) -> Result<Raw, String> {
    if s.is_empty() {
        return Err("Empty line range".to_string());
    }
    if s.starts_with(':') {
        let upper = parse_signed(&s[1..])?;
        return Ok(Raw { lower: 1, upper });
    }
    if s.ends_with(':') {
        let lower = parse_signed(&s[..s.len() - 1])?;
        return Ok(Raw {
            lower,
            upper: OPEN as i128,
        });
    }
    let parts: Vec<&str> = s.split(':').collect();
    match parts.len() {
        n if n >= 4 => Err(
            "Line range contained too many ':' characters. Expected format: 'N', 'N:M', 'N::C', or 'N:M:C'"
                .to_string(),
        ),
        3 => {
            if parts[1].is_empty() {
                let n = parse_unsigned(parts[0])
                    .map_err(|_| "Invalid line number in N::C format".to_string())?;
                let c = parse_unsigned(parts[2])
                    .map_err(|_| "Invalid context number in N::C format".to_string())?;
                Ok(Raw {
                    lower: (n - c).max(0),
                    upper: n + c,
                })
            } else {
                let n = parse_unsigned(parts[0])
                    .map_err(|_| "Invalid start line number in N:M:C format".to_string())?;
