                    .map_err(|_| "Invalid context number in N::C format".to_string())?;
                Ok(Raw {
                    lower: (n - c).max(0),
                    upper: n + c,
                })
            } else {
                let n = parse_unsigned(parts[0])
                    .map_err(|_| "Invalid start line number in N:M:C format".to_string())?;
                let mm = parse_unsigned(parts[1])
                    .map_err(|_| "Invalid end line number in N:M:C format".to_string())?;
                let c = parse_unsigned(parts[2])
                    .map_err(|_| "Invalid context number in N:M:C format".to_string())?;
                Ok(Raw {
                    lower: (n - c).max(0),
                    upper: mm + c,
                })
            }
        }
        2 => {
            let n = parse_unsigned(parts[0])?;
            let rest = parts[1];
            if let Some(r) = rest.strip_prefix('+') {
                let m = parse_unsigned(r).map_err(|_| "Invalid character after +".to_string())?;
                Ok(Raw {
                    lower: n,
                    upper: n + m,
                })
            } else if let Some(r) = rest.strip_prefix('-') {
                let m = parse_unsigned(r)?;
                Ok(Raw {
                    lower: (n - m).max(0),
                    upper: n,
                })
            } else {
                let m = parse_unsigned(rest)?;
                Ok(Raw { lower: n, upper: m })
            }
        }
        _ => {
            let n = parse_unsigned(s)?;
            Ok(Raw { lower: n, upper: n })
        }
    }
}

pub fn parse(s: &str) -> Result<LineRange, String> {
    let raw = parse_raw(s)?;
    Ok(LineRange {
        lower: clamp(raw.lower),
        upper: clamp(raw.upper),
    })
}

fn clamp(v: i128) -> usize {
    if v < 0 {
        // Encoded as a huge value so that unresolved negatives never match.
        // `--line-range` resolves them before this point.
        NEGATIVE_BASE.wrapping_add(v as i64 as usize)
    } else if v > usize::MAX as i128 {
        usize::MAX
    } else {
        v as usize
    }
}

const NEGATIVE_BASE: usize = 0;

/// Resolve end-relative bounds against the total number of lines.
pub fn resolve_against(ranges: &mut LineRanges, raws: &[Raw], total: usize) {
    ranges.ranges.clear();
    for r in raws {
        let lower = if r.lower < 0 {
            let v = total as i128 + r.lower + 1;
            if v < 1 {
                1
            } else {
                v as usize
            }
        } else {
            r.lower.min(usize::MAX as i128) as usize
        };
        let upper = if r.upper < 0 {
            let v = total as i128 + r.upper;
            if v < 0 {
                0
            } else {
                v as usize
            }
        } else {
            r.upper.min(usize::MAX as i128) as usize
        };
        ranges.ranges.push(LineRange { lower, upper });
    }
}

/// Highlight ranges keep negative bounds unresolved.
pub fn as_unresolved(raws: &[Raw]) -> Vec<(i128, i128)> {
    raws.iter().map(|r| (r.lower, r.upper)).collect()
}

