//! Colors and text attributes.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    /// A theme color with its pre-computed 8-bit approximation.
    Rgb { r: u8, g: u8, b: u8, idx: u8 },
    /// One of the terminal's own 16 colors, rendered with the classic SGR codes.
    Ansi(u8),
}

impl Color {
    pub const fn rgb(r: u8, g: u8, b: u8, idx: u8) -> Self {
        Color::Rgb { r, g, b, idx }
    }

    fn sgr(&self, background: bool, true_color: bool) -> String {
        match *self {
            Color::Rgb { r, g, b, idx } => {
                if true_color {
                    format!("{};2;{};{};{}", if background { 48 } else { 38 }, r, g, b)
                } else {
                    format!("{};5;{}", if background { 48 } else { 38 }, idx)
                }
            }
            Color::Ansi(n) => {
                // 0-7 map to 30-37 / 40-47, 8-15 to 90-97 / 100-107.
                let base = if n < 8 {
                    if background {
                        40
                    } else {
                        30
                    }
                } else if background {
                    100
                } else {
                    90
                };
                format!("{}", base + (n % 8) as u32)
            }
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
}

impl Style {
    pub fn fg(c: Color) -> Self {
        Style {
            fg: Some(c),
            ..Default::default()
        }
    }

    pub fn is_plain(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && !self.bold && !self.italic && !self.underline
    }

    /// The SGR introducer for this style, or an empty string if there is nothing
    /// to set.
    pub fn prefix(&self, true_color: bool, allow_italic: bool) -> String {
        let mut parts: Vec<String> = Vec::new();
        if self.bold {
            parts.push("1".to_string());
        }
        if self.italic && allow_italic {
            parts.push("3".to_string());
        }
        if self.underline {
            parts.push("4".to_string());
        }
        if let Some(bg) = self.bg {
            parts.push(bg.sgr(true, true_color));
        }
        if let Some(fg) = self.fg {
            parts.push(fg.sgr(false, true_color));
        }
        if parts.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", parts.join(";"))
        }
    }

    pub fn paint(&self, text: &str, true_color: bool, allow_italic: bool) -> String {
        let p = self.prefix(true_color, allow_italic);
        if p.is_empty() {
            text.to_string()
        } else {
            format!("{}{}\x1b[0m", p, text)
        }
    }
}

